functions.rocket_launch_rules:
execute as @a at @s run playsound minecraft:entity.experience_orb.pickup master @s ~ ~ ~ 10 2 1
scoreboard players add currentRule variables 1
execute if score currentRule variables matches 1 run function mcp:give_ready_ups
execute if score currentRule variables matches 1 in new_dimensions:sky_dimension as @a[scores={minigameplayer=1}] at @s run summon minecraft:marker -62 138 125 {Tags:["mp1","rocket_launch1"]}
