execute if score currentRule variables matches 1 run tellraw @a {fallback:"You must jump off the platform in the indicated direction and use your rocket to boost yourself as far as possible.",translate:"mcp.rocket_launch_rules.1",color:"dark_aqua",type:"translatable"}
execute if score currentRule variables matches 2 run tellraw @a {fallback:"Once you land on the ground, you are finished.",translate:"mcp.rocket_launch_rules.2",color:"dark_green",type:"translatable"}
