execute if score currentRule variables matches 4 run tellraw @a {fallback:"The field ends at 2160 blocks. Any extra height gained at the finish will add on to your score with a tiebreaker being who landed first.",translate:"mcp.rocket_launch_rules.4",color:"dark_green",type:"translatable"}
execute if score currentRule variables matches 1..3 run schedule function mcp:rocket_launch_rules 3s
execute if score currentRule variables matches 4 run function mcp:ready_up_tellraw

